      return amount;
    },
    member: (level) => (amount) => {
      const rates = { normal: 0.9, gold: 0.8, diamond: 0.7 };
      return amount * rates[level];
    },
    category: (cat) => (amount) => {
      const cuts = { '3c': 5, book: 3 };
      return amount - (cuts[cat] || 0);
    }
  };

  const combine = (originalAmount, appliedRules) => {
    let res = originalAmount;
    // 按传入顺序应用所有规则
    appliedRules.forEach(rule => {
      res = rule(res);
    });
    // 互斥过滤：若应用了满减则移除品类折扣
    const hasFull = appliedRules.some(r => r.type === 'full');
    const hasCategory = appliedRules.some(r => r.type === 'category');
    if (hasFull) {
      appliedRules = appliedRules.filter(r => r.type !== 'category');
      res = combine(originalAmount, appliedRules); // 递归重算
    }
    // 全局约束
    if (res < originalAmount * 0.3) res = originalAmount * 0.3;
    return res;
  };

  return rules[type];
};
